#include <string.h>#include "256.h"#include "FileStuff.h"#include "BMP.h"OSErr getOverheadTexture (Str255 thePlugName);OSErr getOverheadTexture (Str255 thePlugName){//----------------------------------vars--------------------------------------------------	short		thePlugFileRef;	OSErr		theError;	FSSpec		thePlugFSSpec;	char *theTexture;	short			theTempWidth, theTempHeight;	long			theWidth, theHeight, theSize, theOffset;		const long		kPaletteOffset		= 384L;	const long		kTheWidthOffset		= 2876L;	const long		kTheHeightOffset	= 2878L;	const long		kTheBitsOffset		= 2928L;	struct Myth256Palette thePalette;//----------------------------------------------------------------------------------------	// plug	theError = FSMakeFSSpec (0L, 0L, thePlugName, &thePlugFSSpec);	if ( theError != noErr )		return theError;	theError = FSpOpenDF ( &thePlugFSSpec, fsCurPerm, &thePlugFileRef );	if ( theError != noErr )		return theError;	FileSeek ( thePlugFileRef, kTheWidthOffset );	FileRead ( &theTempWidth, 2L, thePlugFileRef );	FileSeek ( thePlugFileRef, kTheHeightOffset );	FileRead ( &theTempHeight, 2L, thePlugFileRef );	theWidth = (long) theTempWidth;	theHeight = (long) theTempHeight;		theSize = theWidth * theHeight;		theOffset = 2976 + 4 * theHeight;	FileSeek ( thePlugFileRef, kPaletteOffset );	FileRead ( &thePalette, 2080L, thePlugFileRef );	theTexture = (char *) NewPtr ( theSize );	if ( theTexture == nil ){		FSClose ( thePlugFileRef );		return -1;	}	FileSeek ( thePlugFileRef, theOffset );	FileRead ( theTexture, theSize, thePlugFileRef );	theError = writeBMP( "\p:Graphics.out:overhead.bmp", (long) theWidth, (long) theHeight, &thePalette, theTexture );	DisposePtr ( theTexture );	FSClose ( thePlugFileRef );	return theError;}